const files=[
"/kit-skills/shared/proof-extension-soundness.md",
"/kit-skills/shared/running-k.md",
"/kit-skills/shared/k-syntax.md",
"/kit-skills/shared/k-claims.md",
"/kit-skills/shared/semantics-template.md"
];
const rs=await Promise.all(files.map(f=>tools.exec_command({cmd:`sed -n '1,400p' ${f}`,workdir:"/audit-output",yield_time_ms:10000,max_output_tokens:30000})));
rs.forEach((r,i)=>text(`===${files[i]}===\n${r.output}`));

const cmds=[
  {name:"mount-check",cmd:"if [ -e /reference/reference-semantics ] || [ -L /reference/reference-semantics ]; then echo PRESENT; find -L /reference/reference-semantics -maxdepth 2 -printf '%y %p -> %l\\n' 2>&1; else echo ABSENT; fi"},
  {name:"candidate-tree",cmd:"find /candidate -maxdepth 4 -printf '%y %p -> %l\\n' | sort"},
  {name:"reference-tree",cmd:"find /reference -maxdepth 3 -printf '%y %p -> %l\\n' | sort"},
  {name:"tools",cmd:"export PATH=\"/root/.nix-profile/bin:$PATH\"; command -v kup; command -v kompile; command -v kprove; command -v krun; kompile --version; kprove --version; python3 --version"}
];
const rs=await Promise.all(cmds.map(x=>tools.exec_command({cmd:x.cmd,workdir:"/audit-output",yield_time_ms:10000,max_output_tokens:30000})));
rs.forEach((r,i)=>text(`===${cmds[i].name} exit=${r.exit_code}===\n${r.output}`));

const cmds=[
 {name:"integrity-hashes",cmd:"sha256sum /reference/prompt.py /candidate/prompt.py /reference/py2mpy.py /candidate/py2mpy.py /reference/canonical.py /candidate/solution.py /candidate/solution.mpy /candidate/semantic.k /candidate/lemmas.k /candidate/verification.k /candidate/spec.k; cmp -s /reference/prompt.py /candidate/prompt.py; echo prompt_cmp=$?; cmp -s /reference/py2mpy.py /candidate/py2mpy.py; echo translator_cmp=$?"},
 {name:"trace-tree",cmd:"find /candidate/codex-trace -maxdepth 12 -printf '%y %p -> %l\\n' | sort"},
 {name:"source-sizes",cmd:"wc -l -c /candidate/run-input.json /candidate/metrics.json /candidate/codex-last.txt /candidate/codex-output.log /reference/prompt.py /reference/canonical.py /reference/py2mpy.py /candidate/solution.py /candidate/solution.mpy /candidate/semantic.k /candidate/lemmas.k /candidate/verification.k /candidate/spec.k /candidate/prove.sh"}
];
const rs=await Promise.all(cmds.map(x=>tools.exec_command({cmd:x.cmd,workdir:"/audit-output",yield_time_ms:10000,max_output_tokens:30000})));
rs.forEach((r,i)=>text(`===${cmds[i].name} exit=${r.exit_code}===\n${r.output}`));

const cmds=[
 {name:"untrusted-metadata",cmd:"for f in /candidate/run-input.json /candidate/metrics.json /candidate/codex-last.txt; do echo \"FILE $f\"; sed -n '1,260p' \"$f\"; done; echo 'CODEX_OUTPUT_HEAD'; sed -n '1,80p' /candidate/codex-output.log; echo 'CODEX_OUTPUT_TAIL'; tail -n 120 /candidate/codex-output.log"},
 {name:"program-contract",cmd:"for f in /reference/prompt.py /reference/canonical.py /candidate/solution.py /candidate/solution.mpy; do echo \"FILE $f\"; nl -ba \"$f\"; done"},
 {name:"semantics",cmd:"nl -ba /candidate/semantic.k"},
 {name:"lemmas-verification",cmd:"echo 'FILE lemmas.k'; nl -ba /candidate/lemmas.k; echo 'FILE verification.k'; nl -ba /candidate/verification.k"},
 {name:"spec-prove",cmd:"echo 'FILE spec.k'; nl -ba /candidate/spec.k; echo 'FILE prove.sh'; nl -ba /candidate/prove.sh"}
];
const rs=await Promise.all(cmds.map(x=>tools.exec_command({cmd:x.cmd,workdir:"/audit-output",yield_time_ms:10000,max_output_tokens:40000})));
rs.forEach((r,i)=>text(`===${cmds[i].name} exit=${r.exit_code}===\n${r.output}`));

